    25→    const logs = await proc.getLogs();
    26→    const runningHash = (logs.stdout || '').trim();
    27→
    28→    if (!runningHash) {
    29→      return {
    30→        current: false,
    31→        expectedHash,
    32→        runningHash: null,
    33→        reason: 'No config hash found in container (pre-version gateway)',
    34→      };
    35→    }
    36→
    37→    if (runningHash !== expectedHash) {
    38→      return {
    39→        current: false,
    40→        expectedHash,
    41→        runningHash,
    42→        reason: `Hash mismatch: running=${runningHash}, expected=${expectedHash}`,
    43→      };
    44→    }
    45→
    46→    return { current: true, expectedHash, runningHash };
    47→  } catch (error) {
    48→    return {
    49→      current: false,
