    54→  }
    55→}
    56→
    57→/**
    58→ * Find an existing Moltbot gateway process
    59→ *
    60→ * @param sandbox - The sandbox instance
    61→ * @returns The process if found and running/starting, null otherwise
    62→ */
    63→export async function findExistingMoltbotProcess(sandbox: Sandbox): Promise<Process | null> {
    64→  try {
    65→    const processes = await sandbox.listProcesses();
    66→    for (const proc of processes) {
    67→      // Only match the gateway process, not CLI commands like "clawdbot devices list"
    68→      // Note: CLI is still named "clawdbot" until upstream renames it
    69→      const isGatewayProcess =
    70→        proc.command.includes('start-moltbot.sh') ||
    71→        proc.command.includes('clawdbot gateway');
    72→      const isCliCommand =
    73→        proc.command.includes('clawdbot devices') ||
    74→        proc.command.includes('clawdbot --version');
    75→
    76→      if (isGatewayProcess && !isCliCommand) {
    77→        if (proc.status === 'starting' || proc.status === 'running') {
    78→          return proc;
    79→        }
    80→      }
    81→    }
    82→  } catch (e) {
    83→    console.log('Could not list processes:', e);
    84→  }
    85→  return null;
    86→}
    87→
    88→/**
    89→ * Force restart the Moltbot gateway
    90→ *
    91→ * Kills any existing gateway process and starts a new one.
    92→ * Use this when config changes require a gateway restart.
    93→ */
    94→export async function restartMoltbotGateway(sandbox: Sandbox, env: MoltbotEnv): Promise<Process> {
    95→  // Kill any existing gateway process
    96→  const existingProcess = await findExistingMoltbotProcess(sandbox);
    97→  if (existingProcess) {
    98→    console.log('[restart] Killing existing gateway process:', existingProcess.id);
    99→    try {
   100→      await existingProcess.kill();
   101→      // Wait for process to fully terminate
   102→      await new Promise(resolve => setTimeout(resolve, 2000));
   103→    } catch (killError) {
   104→      console.log('[restart] Failed to kill process (may already be dead):', killError);
   105→    }
   106→  }
   107→
   108→  // Mount R2 storage
   109→  await mountR2Storage(sandbox, env);
   110→
   111→  // Start fresh gateway
   112→  console.log('[restart] Starting fresh Moltbot gateway...');
   113→  const envVars = buildEnvVars(env);
   114→  const command = '/usr/local/bin/start-moltbot.sh';
   115→
   116→  const process = await sandbox.startProcess(command, {
   117→    env: Object.keys(envVars).length > 0 ? envVars : undefined,
   118→  });
   119→  console.log('[restart] Process started:', process.id);
   120→
   121→  // Wait for ready
   122→  await process.waitForPort(MOLTBOT_PORT, { mode: 'tcp', timeout: STARTUP_TIMEOUT_MS });
   123→  console.log('[restart] Gateway is ready!');
   124→
   125→  const logs = await process.getLogs();
   126→  if (logs.stdout) console.log('[restart] stdout:', logs.stdout);
   127→  if (logs.stderr) console.log('[restart] stderr:', logs.stderr);
   128→
   129→  return process;
   130→}
   131→
   132→/**
   133→ * Ensure the Moltbot gateway is running with current config.
   134→ *
   135→ * This will:
   136→ * 1. Mount R2 storage if configured
   137→ * 2. Check for an existing gateway process
   138→ * 3. Verify the gateway has the current config hash
   139→ * 4. If hash mismatch, kill and restart with new config
   140→ * 5. Wait for it to be ready, or start a new one
   141→ *
   142→ * @param sandbox - The sandbox instance
   143→ * @param env - Worker environment bindings
   144→ * @returns The running gateway process
   145→ */
   146→export async function ensureMoltbotGateway(sandbox: Sandbox, env: MoltbotEnv): Promise<Process> {
   147→  // Mount R2 storage for persistent data (non-blocking if not configured)
   148→  // R2 is used as a backup - the startup script will restore from it on boot
   149→  await mountR2Storage(sandbox, env);
   150→
   151→  // Check if Moltbot is already running or starting
   152→  const existingProcess = await findExistingMoltbotProcess(sandbox);
   153→  if (existingProcess) {
   154→    console.log('Found existing Moltbot process:', existingProcess.id, 'status:', existingProcess.status);
   155→
   156→    // Check if the running gateway has the current config
   157→    const versionCheck = await isGatewayCurrentVersion(sandbox, env);
   158→    if (!versionCheck.current) {
   159→      console.log('[version] Gateway config mismatch:', versionCheck.reason);
   160→      console.log('[version] Killing outdated gateway and restarting with new config...');
   161→      try {
   162→        await existingProcess.kill();
   163→        // Wait for process to fully terminate
   164→        await new Promise(resolve => setTimeout(resolve, 2000));
   165→      } catch (killError) {
   166→        console.log('[version] Failed to kill process (may already be dead):', killError);
   167→      }
   168→      // Fall through to start a new gateway with updated config
